 61→// InstallHooks installs Factory AI Droid hooks in .factory/settings.json.
 62→// If force is true, removes existing Entire hooks before installing.
 63→// Returns the number of hooks installed.
 64→func (f *FactoryAIDroidAgent) InstallHooks(localDev bool, force bool) (int, error) {
 65→	// Use repo root instead of CWD to find .factory directory
 66→	// This ensures hooks are installed correctly when run from a subdirectory
 67→	repoRoot, err := paths.RepoRoot()
 68→	if err != nil {
 69→		// Fallback to CWD if not in a git repo (e.g., during tests)
 70→		repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when RepoRoot() fails (tests run outside git repos)
 71→		if err != nil {
 72→			return 0, fmt.Errorf("failed to get current directory: %w", err)
 73→		}
 74→	}
 75→
 76→	settingsPath := filepath.Join(repoRoot, ".factory", FactorySettingsFileName)
 77→
 78→	// Read existing settings if they exist
 79→	var rawSettings map[string]json.RawMessage
 80→
 81→	// rawHooks preserves unknown hook types
 82→	var rawHooks map[string]json.RawMessage
 83→
 84→	// rawPermissions preserves unknown permission fields (e.g., "ask")
 85→	var rawPermissions map[string]json.RawMessage
 86→
 87→	existingData, readErr := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from cwd + fixed path
 88→	if readErr == nil {
 89→		if err := json.Unmarshal(existingData, &rawSettings); err != nil {
 90→			return 0, fmt.Errorf("failed to parse existing settings.json: %w", err)
 91→		}
 92→		if hooksRaw, ok := rawSettings["hooks"]; ok {
 93→			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 94→				return 0, fmt.Errorf("failed to parse hooks in settings.json: %w", err)
 95→			}
 96→		}
 97→		if permRaw, ok := rawSettings["permissions"]; ok {
 98→			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
 99→				return 0, fmt.Errorf("failed to parse permissions in settings.json: %w", err)
100→			}
101→		}
102→	} else {
103→		rawSettings = make(map[string]json.RawMessage)
104→	}
105→
106→	if rawHooks == nil {
107→		rawHooks = make(map[string]json.RawMessage)
108→	}
109→	if rawPermissions == nil {
110→		rawPermissions = make(map[string]json.RawMessage)
111→	}
112→
113→	// Parse only the hook types we need to modify
114→	var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse, preCompact []FactoryHookMatcher
115→	parseHookType(rawHooks, "SessionStart", &sessionStart)
116→	parseHookType(rawHooks, "SessionEnd", &sessionEnd)
117→	parseHookType(rawHooks, "Stop", &stop)
118→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
119→	parseHookType(rawHooks, "PreToolUse", &preToolUse)
120→	parseHookType(rawHooks, "PostToolUse", &postToolUse)
121→	parseHookType(rawHooks, "PreCompact", &preCompact)
122→
123→	// If force is true, remove all existing Entire hooks first
124→	if force {
125→		sessionStart = removeEntireHooks(sessionStart)
126→		sessionEnd = removeEntireHooks(sessionEnd)
127→		stop = removeEntireHooks(stop)
128→		userPromptSubmit = removeEntireHooks(userPromptSubmit)
129→		preToolUse = removeEntireHooksFromMatchers(preToolUse)
130→		postToolUse = removeEntireHooksFromMatchers(postToolUse)
131→		preCompact = removeEntireHooks(preCompact)
132→	}
133→
134→	// Define hook commands
135→	var sessionStartCmd, sessionEndCmd, stopCmd, userPromptSubmitCmd, preTaskCmd, postTaskCmd, preCompactCmd string
136→	if localDev {
137→		sessionStartCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid session-start"
138→		sessionEndCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid session-end"
139→		stopCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid stop"
140→		userPromptSubmitCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid user-prompt-submit"
141→		preTaskCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid pre-tool-use"
142→		postTaskCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid post-tool-use"
143→		preCompactCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid pre-compact"
144→	} else {
145→		sessionStartCmd = "entire hooks factoryai-droid session-start"
146→		sessionEndCmd = "entire hooks factoryai-droid session-end"
147→		stopCmd = "entire hooks factoryai-droid stop"
148→		userPromptSubmitCmd = "entire hooks factoryai-droid user-prompt-submit"
149→		preTaskCmd = "entire hooks factoryai-droid pre-tool-use"
150→		postTaskCmd = "entire hooks factoryai-droid post-tool-use"
151→		preCompactCmd = "entire hooks factoryai-droid pre-compact"
152→	}
153→
154→	count := 0
155→
156→	// Add hooks if they don't exist
157→	if !hookCommandExists(sessionStart, sessionStartCmd) {
158→		sessionStart = addHookToMatcher(sessionStart, "", sessionStartCmd)
159→		count++
160→	}
161→	if !hookCommandExists(sessionEnd, sessionEndCmd) {
162→		sessionEnd = addHookToMatcher(sessionEnd, "", sessionEndCmd)
163→		count++
164→	}
165→	if !hookCommandExists(stop, stopCmd) {
166→		stop = addHookToMatcher(stop, "", stopCmd)
167→		count++
168→	}
169→	if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
170→		userPromptSubmit = addHookToMatcher(userPromptSubmit, "", userPromptSubmitCmd)
171→		count++
172→	}
173→	if !hookCommandExistsWithMatcher(preToolUse, "Task", preTaskCmd) {
174→		preToolUse = addHookToMatcher(preToolUse, "Task", preTaskCmd)
175→		count++
176→	}
177→	if !hookCommandExistsWithMatcher(postToolUse, "Task", postTaskCmd) {
178→		postToolUse = addHookToMatcher(postToolUse, "Task", postTaskCmd)
179→		count++
180→	}
181→	if !hookCommandExists(preCompact, preCompactCmd) {
182→		preCompact = addHookToMatcher(preCompact, "", preCompactCmd)
183→		count++
184→	}
185→
186→	// Add permissions.deny rule if not present
187→	permissionsChanged := false
188→	var denyRules []string
189→	if denyRaw, ok := rawPermissions["deny"]; ok {
190→		if err := json.Unmarshal(denyRaw, &denyRules); err != nil {
191→			return 0, fmt.Errorf("failed to parse permissions.deny in settings.json: %w", err)
192→		}
193→	}
194→	if !slices.Contains(denyRules, metadataDenyRule) {
195→		denyRules = append(denyRules, metadataDenyRule)
196→		denyJSON, err := json.Marshal(denyRules)
197→		if err != nil {
198→			return 0, fmt.Errorf("failed to marshal permissions.deny: %w", err)
199→		}
200→		rawPermissions["deny"] = denyJSON
201→		permissionsChanged = true
202→	}
203→
204→	if count == 0 && !permissionsChanged {
205→		return 0, nil // All hooks and permissions already installed
206→	}
207→
208→	// Marshal modified hook types back to rawHooks
209→	marshalHookType(rawHooks, "SessionStart", sessionStart)
210→	marshalHookType(rawHooks, "SessionEnd", sessionEnd)
211→	marshalHookType(rawHooks, "Stop", stop)
212→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
213→	marshalHookType(rawHooks, "PreToolUse", preToolUse)
214→	marshalHookType(rawHooks, "PostToolUse", postToolUse)
215→	marshalHookType(rawHooks, "PreCompact", preCompact)
216→
217→	// Marshal hooks and update raw settings
218→	hooksJSON, err := json.Marshal(rawHooks)
219→	if err != nil {
220→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
221→	}
222→	rawSettings["hooks"] = hooksJSON
223→
224→	// Marshal permissions and update raw settings
225→	permJSON, err := json.Marshal(rawPermissions)
226→	if err != nil {
227→		return 0, fmt.Errorf("failed to marshal permissions: %w", err)
228→	}
229→	rawSettings["permissions"] = permJSON
230→
231→	// Write back to file
232→	if err := os.MkdirAll(filepath.Dir(settingsPath), 0o750); err != nil {
233→		return 0, fmt.Errorf("failed to create .factory directory: %w", err)
234→	}
235→
236→	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
237→	if err != nil {
238→		return 0, fmt.Errorf("failed to marshal settings: %w", err)
239→	}
240→
241→	if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
242→		return 0, fmt.Errorf("failed to write settings.json: %w", err)
243→	}
244→
245→	return count, nil
246→}
