271→// UninstallHooks removes Entire hooks from Factory AI Droid settings.
272→func (f *FactoryAIDroidAgent) UninstallHooks() error {
273→	// Use repo root to find .factory directory when run from a subdirectory
274→	repoRoot, err := paths.RepoRoot()
275→	if err != nil {
276→		repoRoot = "." // Fallback to CWD if not in a git repo
277→	}
278→	settingsPath := filepath.Join(repoRoot, ".factory", FactorySettingsFileName)
279→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
280→	if err != nil {
281→		return nil //nolint:nilerr // No settings file means nothing to uninstall
282→	}
283→
284→	var rawSettings map[string]json.RawMessage
285→	if err := json.Unmarshal(data, &rawSettings); err != nil {
286→		return fmt.Errorf("failed to parse settings.json: %w", err)
287→	}
288→
289→	// rawHooks preserves unknown hook types
290→	var rawHooks map[string]json.RawMessage
291→	if hooksRaw, ok := rawSettings["hooks"]; ok {
292→		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
293→			return fmt.Errorf("failed to parse hooks: %w", err)
294→		}
295→	}
296→	if rawHooks == nil {
297→		rawHooks = make(map[string]json.RawMessage)
298→	}
299→
300→	// Parse only the hook types we need to modify
301→	var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse, preCompact []FactoryHookMatcher
302→	parseHookType(rawHooks, "SessionStart", &sessionStart)
303→	parseHookType(rawHooks, "SessionEnd", &sessionEnd)
304→	parseHookType(rawHooks, "Stop", &stop)
305→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
306→	parseHookType(rawHooks, "PreToolUse", &preToolUse)
307→	parseHookType(rawHooks, "PostToolUse", &postToolUse)
308→	parseHookType(rawHooks, "PreCompact", &preCompact)
309→
310→	// Remove Entire hooks from all hook types
311→	sessionStart = removeEntireHooks(sessionStart)
312→	sessionEnd = removeEntireHooks(sessionEnd)
313→	stop = removeEntireHooks(stop)
314→	userPromptSubmit = removeEntireHooks(userPromptSubmit)
315→	preToolUse = removeEntireHooksFromMatchers(preToolUse)
316→	postToolUse = removeEntireHooksFromMatchers(postToolUse)
317→	preCompact = removeEntireHooks(preCompact)
318→
319→	// Marshal modified hook types back to rawHooks
320→	marshalHookType(rawHooks, "SessionStart", sessionStart)
321→	marshalHookType(rawHooks, "SessionEnd", sessionEnd)
322→	marshalHookType(rawHooks, "Stop", stop)
323→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
324→	marshalHookType(rawHooks, "PreToolUse", preToolUse)
325→	marshalHookType(rawHooks, "PostToolUse", postToolUse)
326→	marshalHookType(rawHooks, "PreCompact", preCompact)
327→
328→	// Also remove the metadata deny rule from permissions
329→	var rawPermissions map[string]json.RawMessage
330→	if permRaw, ok := rawSettings["permissions"]; ok {
331→		if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
332→			// If parsing fails, just skip permissions cleanup
333→			rawPermissions = nil
334→		}
335→	}
336→
337→	if rawPermissions != nil {
338→		if denyRaw, ok := rawPermissions["deny"]; ok {
339→			var denyRules []string
340→			if err := json.Unmarshal(denyRaw, &denyRules); err == nil {
341→				// Filter out the metadata deny rule
342→				filteredRules := make([]string, 0, len(denyRules))
343→				for _, rule := range denyRules {
344→					if rule != metadataDenyRule {
345→						filteredRules = append(filteredRules, rule)
346→					}
347→				}
348→				if len(filteredRules) > 0 {
349→					denyJSON, err := json.Marshal(filteredRules)
350→					if err == nil {
351→						rawPermissions["deny"] = denyJSON
352→					}
353→				} else {
354→					// Remove empty deny array
355→					delete(rawPermissions, "deny")
356→				}
357→			}
358→		}
359→
360→		// If permissions is empty, remove it entirely
361→		if len(rawPermissions) > 0 {
362→			permJSON, err := json.Marshal(rawPermissions)
363→			if err == nil {
364→				rawSettings["permissions"] = permJSON
365→			}
366→		} else {
367→			delete(rawSettings, "permissions")
368→		}
369→	}
370→
371→	// Marshal hooks back (preserving unknown hook types)
372→	if len(rawHooks) > 0 {
373→		hooksJSON, err := json.Marshal(rawHooks)
374→		if err != nil {
375→			return fmt.Errorf("failed to marshal hooks: %w", err)
376→		}
377→		rawSettings["hooks"] = hooksJSON
378→	} else {
379→		delete(rawSettings, "hooks")
380→	}
381→
382→	// Write back
383→	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
384→	if err != nil {
385→		return fmt.Errorf("failed to marshal settings: %w", err)
386→	}
387→	if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
388→		return fmt.Errorf("failed to write settings.json: %w", err)
389→	}
390→	return nil
391→}
