428→// Helper functions for hook management
429→
430→func hookCommandExists(matchers []FactoryHookMatcher, command string) bool {
431→	for _, matcher := range matchers {
432→		for _, hook := range matcher.Hooks {
433→			if hook.Command == command {
434→				return true
435→			}
436→		}
437→	}
438→	return false
439→}
440→
441→func hookCommandExistsWithMatcher(matchers []FactoryHookMatcher, matcherName, command string) bool {
442→	for _, matcher := range matchers {
443→		if matcher.Matcher == matcherName {
444→			for _, hook := range matcher.Hooks {
445→				if hook.Command == command {
446→					return true
447→				}
448→			}
449→		}
450→	}
451→	return false
452→}
453→
454→func addHookToMatcher(matchers []FactoryHookMatcher, matcherName, command string) []FactoryHookMatcher {
455→	entry := FactoryHookEntry{
456→		Type:    "command",
457→		Command: command,
458→	}
459→
460→	// If no matcher name, add to a matcher with empty string
461→	if matcherName == "" {
462→		for i, matcher := range matchers {
463→			if matcher.Matcher == "" {
464→				matchers[i].Hooks = append(matchers[i].Hooks, entry)
465→				return matchers
466→			}
467→		}
468→		return append(matchers, FactoryHookMatcher{
469→			Matcher: "",
470→			Hooks:   []FactoryHookEntry{entry},
471→		})
472→	}
473→
474→	// Find or create matcher with the given name
475→	for i, matcher := range matchers {
476→		if matcher.Matcher == matcherName {
477→			matchers[i].Hooks = append(matchers[i].Hooks, entry)
478→			return matchers
479→		}
480→	}
481→
482→	return append(matchers, FactoryHookMatcher{
483→		Matcher: matcherName,
484→		Hooks:   []FactoryHookEntry{entry},
485→	})
486→}
