488→// isEntireHook checks if a command is an Entire hook (old or new format)
489→func isEntireHook(command string) bool {
490→	for _, prefix := range entireHookPrefixes {
491→		if strings.HasPrefix(command, prefix) {
492→			return true
493→		}
494→	}
495→	return false
496→}
497→
498→// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
499→func removeEntireHooks(matchers []FactoryHookMatcher) []FactoryHookMatcher {
500→	result := make([]FactoryHookMatcher, 0, len(matchers))
501→	for _, matcher := range matchers {
502→		filteredHooks := make([]FactoryHookEntry, 0, len(matcher.Hooks))
503→		for _, hook := range matcher.Hooks {
504→			if !isEntireHook(hook.Command) {
505→				filteredHooks = append(filteredHooks, hook)
506→			}
507→		}
508→		// Only keep the matcher if it has hooks remaining
509→		if len(filteredHooks) > 0 {
510→			matcher.Hooks = filteredHooks
511→			result = append(result, matcher)
512→		}
513→	}
514→	return result
515→}
516→
517→// removeEntireHooksFromMatchers removes Entire hooks from tool-use matchers (PreToolUse, PostToolUse)
518→// This handles the nested structure where hooks are grouped by tool matcher (e.g., "Task")
519→func removeEntireHooksFromMatchers(matchers []FactoryHookMatcher) []FactoryHookMatcher {
520→	// Same logic as removeEntireHooks - both work on the same structure
521→	return removeEntireHooks(matchers)
522→}
