 13→func TestInstallHooks_FreshInstall(t *testing.T) {
 14→	tempDir := t.TempDir()
 15→	t.Chdir(tempDir)
 16→
 17→	agent := &FactoryAIDroidAgent{}
 18→	count, err := agent.InstallHooks(false, false)
 19→	if err != nil {
 20→		t.Fatalf("InstallHooks() error = %v", err)
 21→	}
 22→
 23→	// 7 hooks: SessionStart, SessionEnd, Stop, UserPromptSubmit, PreToolUse[Task], PostToolUse[Task], PreCompact
 24→	if count != 7 {
 25→		t.Errorf("InstallHooks() count = %d, want 7", count)
 26→	}
 27→
 28→	// Verify settings.json was created with hooks
 29→	settings := readFactorySettings(t, tempDir)
 30→
 31→	if len(settings.Hooks.SessionStart) != 1 {
 32→		t.Errorf("SessionStart hooks = %d, want 1", len(settings.Hooks.SessionStart))
 33→	}
 34→	if len(settings.Hooks.SessionEnd) != 1 {
 35→		t.Errorf("SessionEnd hooks = %d, want 1", len(settings.Hooks.SessionEnd))
 36→	}
 37→	if len(settings.Hooks.Stop) != 1 {
 38→		t.Errorf("Stop hooks = %d, want 1", len(settings.Hooks.Stop))
 39→	}
 40→	if len(settings.Hooks.UserPromptSubmit) != 1 {
